import {registerCardComponent} from "@pihanga2/core";

import {LoadingOverlayComponent} from "./loadingOverlay.component";
import {LOADING_OVERLAY_CARD} from "./loadingOverlay.types";

export * from "./loadingOverlay.types";

registerCardComponent({
  name: LOADING_OVERLAY_CARD,
  component: LoadingOverlayComponent,
});

import * as React from "react";
import clsx from "clsx";

import {Card, type PiCardProps} from "@pihanga2/core";

import {Spinner} from "@/components/ui/spinner";

import type {LoadingOverlayProps} from "./loadingOverlay.types";
import "./loadingOverlay.css";

export const LoadingOverlayComponent = (
  props: PiCardProps<LoadingOverlayProps>,
): React.ReactNode => {
  const {
    cardName,
    content,
    isLoading,
    label,
    fillParent,
    viewportCentered,
    className,
    contentClassName,
    overlayClassName,
  } = props;

  if (!content) return null;

  return (
    <div
      data-pihanga={cardName}
      className={clsx(
        "overlay-wrapper",
        isLoading && "is-loading",
        fillParent && "fill-parent",
        viewportCentered && "viewport-centered",
        className,
      )}
    >
      <div className={clsx("overlay-content", contentClassName)}>
        <Card cardName={content} parentCard={cardName} />
        <div className={clsx("loading-overlay", overlayClassName)}>
          <div className="loading-overlay__content">
            <Spinner size="icon" />
            <span>{label ?? "Loading..."}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

.overlay-wrapper {
  position: relative;
  width: 100%;
  min-width: 0;

  display: flex;
  flex-direction: column;
}

.overlay-wrapper.is-loading.fill-parent {
  min-height: 12rem;
}

.overlay-content {
  position: relative;
  width: 100%;
  min-width: 0;

  display: flex;
  flex-direction: column;
  overflow-y: hidden;
  /* Prevent double scrollbars */
  flex-grow: 1;
}

.overlay-wrapper.fill-parent .overlay-content {
  min-height: inherit;
}

.loading-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  /* 70% opaque background — adapts to light/dark via --background */
  background: color-mix(in srgb, var(--background) 70%, transparent);
  opacity: 0;
  pointer-events: none;
  transition: opacity 150ms ease;
  z-index: 2;
}

.overlay-wrapper.viewport-centered .loading-overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
}

.overlay-wrapper.is-loading .loading-overlay {
  opacity: 1;
  pointer-events: auto;
}

.loading-overlay__content {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

import {createCardDeclaration, type PiCardRef} from "@pihanga2/core";

export const LOADING_OVERLAY_CARD = "loading-overlay";

export type LoadingOverlayProps = {
  content: PiCardRef;
  isLoading?: boolean;
  label?: string;
  fillParent?: boolean;
  viewportCentered?: boolean;
  className?: string;
  contentClassName?: string;
  overlayClassName?: string;
};

export const LoadingOverlay = createCardDeclaration<LoadingOverlayProps>(
  LOADING_OVERLAY_CARD,
);
